def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                desperate_count += 1
            if opp.get('budget', 0) > budget:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    prev_bids.sort()
    highest_prev = prev_bids[-1] if prev_bids else 0.0
    second_prev = prev_bids[-2] if len(prev_bids) >= 2 else highest_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22
    critical_me = (hp <= 3) or (no_water >= 1)
    very_critical = (hp <= 2) or (no_water >= 2)

    if very_critical:
        target = max(92.0, second_prev + 3.0, avg_prev * 0.95)
        if tight_supply:
            target = max(target, highest_prev + 2.0)
        return float(min(budget, target))

    if critical_me:
        target = max(78.0, second_prev + 2.0)
        if tight_supply:
            target = max(target, highest_prev + 1.0)
        elif loose_supply:
            target = max(62.0, avg_prev * 0.72)
        return float(min(budget, target))

    if loose_supply:
        target = 16.0
        if desperate_count >= 2:
            target = 22.0
        if rich_count >= 2 and highest_prev > 100:
            target = 12.0
        return float(min(budget, target))

    if tight_supply:
        target = max(74.0, second_prev + 1.5)
        if highest_prev >= 120:
            target = 68.0
        if desperate_count >= 2:
            target = max(target, 82.0)
        return float(min(budget, target))

    target = 46.0
    if highest_prev >= 110:
        target = 38.0
    elif highest_prev >= 90:
        target = 44.0
    else:
        target = max(42.0, avg_prev * 0.5)

    if day >= 8 and hp >= 5 and no_water == 0:
        target *= 0.9

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    # Get yesterday's max bid among alive opponents
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    max_prev_bid = max(prev_bids) if prev_bids else 0
    # Determine aggression factor
    aggression = 1.0
    if max_prev_bid > DAILY_SALARY * 1.2:  # very aggressive opponents
        if my_status['hp'] > 3:
            aggression = 0.3
        else:
            aggression = 0.9
    else:
        if my_status['no_water_days'] >= 1 or my_status['hp'] <= 2:
            aggression = 0.95
        else:
            aggression = 0.6
    # Baseline bid: DAILY_SALARY * (WATER_REQ / supply) but adjust
    supply = day_context['supply']
    # Calculate proportional share as float, then multiply
    # To avoid float index, not using list here
    proportional_bid = DAILY_SALARY * (WATER_REQ / supply)
    bid = min(my_status['budget'], proportional_bid * aggression)
    # Ensure we don't go below 1
    bid = max(bid, 1)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    # Alive opponents and yesterday bids
    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    # If no opponents alive, bid conservatively
    if not alive_opponents:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    yesterday_bids = []
    yesterday_highest = None
    yesterday_second = None
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is None:
            continue
        try:
            b = float(bid)
        except Exception:
            continue
        yesterday_bids.append(b)

    if yesterday_bids:
        yesterday_highest = max(yesterday_bids)
        sorted_bids = sorted(yesterday_bids, reverse=True)
        if len(sorted_bids) > 1:
            yesterday_second = sorted_bids[1]

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Pressure thresholds based on salary
    high_pressure = 0.85 * DAILY_SALARY  # 68

    # Estimate how many water units might be available; use supply/WATER_REQ as a rough proxy
    # Ensure indices are int where needed (none used here), but keep computations safe.
    supply_units = float(supply) / float(WATER_REQ) if WATER_REQ else 0.0

    # Baseline strategy: aim around mid salary to stay competitive but not overspend.
    # If supply is low, increase a bit; if high, decrease.
    if supply_units <= 2.0:
        baseline = DAILY_SALARY * 0.65
    elif supply_units <= 3.0:
        baseline = DAILY_SALARY * 0.55
    else:
        baseline = DAILY_SALARY * 0.50

    # React to yesterday highest bid: if someone was bidding aggressively, we slightly undercut.
    if yesterday_highest is not None:
        if yesterday_highest >= high_pressure:
            # If my hp is low, spend more to prevent death.
            if my_hp <= 2.0:
                target = DAILY_SALARY * 0.95
            else:
                # Undercut aggressive pressure; bid near but below the leader.
                target = min(DAILY_SALARY * 0.75, yesterday_highest * 0.93)
        else:
            # If yesterday bids were moderate, bid near the upper end of baseline.
            if yesterday_second is not None:
                target = max(baseline, min(DAILY_SALARY * 0.62, yesterday_second * 0.98))
            else:
                target = max(baseline, DAILY_SALARY * 0.58)
    else:
        target = baseline

    # If my hp is critical, override to ensure survival.
    if my_hp <= 1.0:
        target = DAILY_SALARY * 0.98
    elif my_hp <= 3.0:
        target = max(target, DAILY_SALARY * 0.78)

    # Budget cap and gentle saving: don't spend more than a fraction of budget.
    # Use no_water_days to increase urgency.
    no_water_days = float(my_status.get('no_water_days', 0.0))
    urgency = 1.0
    if no_water_days >= 2.0:
        urgency = 1.12
    elif no_water_days >= 1.0:
        urgency = 1.06

    target *= urgency

    # Final bid within budget
    bid = float(min(my_budget, target))

    # If budget is extremely low, bid whatever remains.
    if my_budget <= 0.0:
        return 0.0

    # Avoid negative or NaN
    if bid != bid or bid < 0.0:
        return 0.0

    return bid

